"""1228n (#61, 1214an): Test-UseVariants-v1228m.ps1 with -FreeCam. The observer turns toward the use (its own body stays
where it stands), takes the pitch, and the camera is held with coop_observer_camera hold_at at the computed spot (-Back
behind the source along its line to the target, -Side across, eye -EyeHeight above the source's feet). No body teleport, so
no falls from platforms, walls in the way or auto-crouch at cramped spots."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Test-UseVariants-v1228m.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)
rep("[string[]]$Only=@('locks','taps','window'))", "[string[]]$Only=@('locks','taps','window'),[switch]$FreeCam,[double]$EyeHeight=1.65)\n"
    "# 1228n (#61): -FreeCam holds the observer camera at the computed spot with hold_at; the observer body stays put.\n# Generated by make_use_variants_v1228n.py.")
rep("""  for($h=0;$h-lt3;$h++){C $obs ("setviewpos {0:F3} {1:F3} {2:F3} {3:F2} 0"-f$ox,$oy,($sp[2]+1.75),$oyaw);C $obs 'coop_observer_camera hold';Start-Sleep -Milliseconds 500;$hold=S $obs '.observer-camera.json';if($hold.active){break};C $obs 'coop_observer_camera off';Start-Sleep -Milliseconds 700}""",
"""  if($FreeCam){$op=(Q $obs '--player').candidatePosition;$row.observerBody=$op
   for($h=0;$h-lt3;$h++){C $obs ("setviewpos {0:F3} {1:F3} {2:F3} {3:F2} 0"-f[double]$op[0],[double]$op[1],([double]$op[2]+1.7),$oyaw);Start-Sleep -Milliseconds 300;Pitch $obs $ObserverPitch|Out-Null;Start-Sleep -Milliseconds 200
    C $obs ("coop_observer_camera hold_at {0:F3} {1:F3} {2:F3}"-f$ox,$oy,([double]$sp[2]+$EyeHeight));Start-Sleep -Milliseconds 500;$hold=S $obs '.observer-camera.json';if($hold.active){break};C $obs 'coop_observer_camera off';Start-Sleep -Milliseconds 700}}
  else{for($h=0;$h-lt3;$h++){C $obs ("setviewpos {0:F3} {1:F3} {2:F3} {3:F2} 0"-f$ox,$oy,($sp[2]+1.75),$oyaw);C $obs 'coop_observer_camera hold';Start-Sleep -Milliseconds 500;$hold=S $obs '.observer-camera.json';if($hold.active){break};C $obs 'coop_observer_camera off';Start-Sleep -Milliseconds 700}}""")
# The post-hold re-teleport puts the body near the spot; with -FreeCam the body stays put.
rep("""  C $obs ("setviewpos {0:F3} {1:F3} {2:F3} {3:F2} 0"-f$ox,$oy,($sp[2]+1.9),$oyaw);Start-Sleep -Milliseconds 1200""",
"""  if(!$FreeCam){C $obs ("setviewpos {0:F3} {1:F3} {2:F3} {3:F2} 0"-f$ox,$oy,($sp[2]+1.9),$oyaw)};Start-Sleep -Milliseconds 1200""")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Test-UseVariants-v1228n.ps1').write_bytes(out.encode('utf-8'))
print('ok')
